    float lum(float3 c) {
        return dot(c, float3(0.2126, 0.7152, 0.0722));
    }
    float3 rgb2hsl(float3 c) {
        float mx = max(c.r, max(c.g, c.b));
        float mn = min(c.r, min(c.g, c.b));
        float l = (mx + mn) * 0.5;
        float d = mx - mn;
        float s = 0.0;
        float h = 0.0;
        if (d > 0.00001) {
            s = (l > 0.5) ? d / max(2.0 - mx - mn, 0.00001) : d / max(mx + mn, 0.00001);
            if (mx == c.r) { h = (c.g - c.b) / d + (c.g < c.b ? 6.0 : 0.0); }
            else if (mx == c.g) { h = (c.b - c.r) / d + 2.0; }
            else { h = (c.r - c.g) / d + 4.0; }
            h /= 6.0;
        }
        return float3(h, s, l);
    }
    float h2r(float p, float q, float t) {
        if (t < 0.0) t += 1.0;
        if (t > 1.0) t -= 1.0;
        if (t < 1.0/6.0) return p + (q - p) * 6.0 * t;
        if (t < 0.5) return q;
        if (t < 2.0/3.0) return p + (q - p) * (2.0/3.0 - t) * 6.0;
        return p;
    }
    float3 hsl2rgb(float3 c) {
        if (c.y < 0.00001) return float3(c.z);
        float q = (c.z < 0.5) ? c.z * (1.0 + c.y) : c.z + c.y - c.z * c.y;
        float p = 2.0 * c.z - q;
        return float3(h2r(p,q,c.x+1.0/3.0), h2r(p,q,c.x), h2r(p,q,c.x-1.0/3.0));
    }
    float noiseHash(float2 p) {
        float3 p3 = fract(float3(p.xyx) * 0.1031);
        p3 += dot(p3, p3.yzx + 33.33);
        return fract((p3.x + p3.y) * p3.z);
    }
    float applyCurve5(float x, float b, float s, float m, float h, float w) {
        float result = x;
        float bN = b / 100.0;
        float sN = s / 100.0;
        float mN = m / 100.0;
        float hN = h / 100.0;
        float wN = w / 100.0;
        float wBlacks = smoothstep(0.15, 0.0, x);
        result += bN * wBlacks * 0.5;
        float wShadows = smoothstep(0.0, 0.12, x) * smoothstep(0.4, 0.2, x);
        result += sN * wShadows * 0.5;
        float wMids = smoothstep(0.15, 0.35, x) * smoothstep(0.85, 0.65, x);
        result += mN * wMids * 0.5;
        float wHighs = smoothstep(0.6, 0.8, x) * smoothstep(1.0, 0.88, x);
        result += hN * wHighs * 0.5;
        float wWhites = smoothstep(0.85, 1.0, x);
        result += wN * wWhites * 0.5;
        return clamp(result, 0.0, 1.0);
    }
    float applyCurve3(float x, float s, float m, float h) {
        float result = x;
        float sN = s / 100.0;
        float mN = m / 100.0;
        float hN = h / 100.0;
        float wS = smoothstep(0.4, 0.0, x);
        result += sN * wS * 0.5;
        float wM = smoothstep(0.0, 0.3, x) * smoothstep(1.0, 0.7, x);
        result += mN * wM * 0.5;
        float wH = smoothstep(0.6, 1.0, x);
        result += hN * wH * 0.5;
        return clamp(result, 0.0, 1.0);
    }
    float3 applyWhiteBalance(float3 rgb) {
        if (abs(amzp_temperature) < 0.5 && abs(amzp_tint) < 0.5) return rgb;
        float t = amzp_temperature / 100.0;
        float tn = amzp_tint / 100.0;
        float warm = t * 0.08;
        rgb.r += warm;
        rgb.b -= warm;
        rgb.g += warm * 0.15;
        rgb.g += tn * 0.08;
        rgb.r -= tn * 0.03;
        rgb.b -= tn * 0.03;
        return rgb;
    }
    float3 applyExposure(float3 rgb) {
        if (abs(amzp_exposure) < 0.00001) return rgb;
        return rgb * pow(2.0, amzp_exposure);
    }
    float3 applyContrast(float3 rgb) {
        if (abs(amzp_contrast) < 0.5) return rgb;
        float c = amzp_contrast / 100.0;
        float pivot = 0.18;
        float factor = 1.0 + c;
        rgb = (rgb - pivot) * factor + pivot;
        if (c > 0.0) {
            float strength = c * 0.3;
            rgb = rgb + strength * (rgb - 0.5) * (1.0 - abs(rgb - 0.5) * 2.0);
        }
        return rgb;
    }
    float3 applyHighlightsShadows(float3 rgb) {
        float l = lum(rgb);
        float shadowMask = 1.0 - smoothstep(0.0, 0.5, l);
        shadowMask *= shadowMask;
        float highlightMask = smoothstep(0.5, 1.0, l);
        highlightMask *= highlightMask;
        float whiteMask = smoothstep(0.75, 1.0, l);
        float blackMask = 1.0 - smoothstep(0.0, 0.25, l);
        float sAdj = amzp_shadows / 100.0 * 0.4;
        float hAdj = amzp_highlights / 100.0 * 0.4;
        float wAdj = amzp_whites / 100.0 * 0.25;
        float bAdj = amzp_blacks / 100.0 * 0.25;
        float origLum = max(l, 0.00001);
        float newLum = l + sAdj * shadowMask + hAdj * highlightMask + wAdj * whiteMask + bAdj * blackMask;
        float ratio = max(newLum, 0.0) / origLum;
        rgb *= ratio;
        return rgb;
    }
    float3 applySaturation(float3 rgb) {
        if (abs(amzp_saturation - 100.0) < 0.5) return rgb;
        float s = amzp_saturation / 100.0;
        float l = lum(rgb);
        return mix(float3(l), rgb, s);
    }
    float3 applyVibrance(float3 rgb) {
        if (abs(amzp_vibrance) < 0.5) return rgb;
        float v = amzp_vibrance / 100.0;
        float l = lum(rgb);
        float currentSat = length(rgb - float3(l));
        float weight = 1.0 - clamp(currentSat * 3.0, 0.0, 1.0);
        float boost = 1.0 + v * weight;
        return mix(float3(l), rgb, boost);
    }
    float3 applyClarity(float3 rgb, float2 uv) {
        if (abs(amzp_clarity) < 0.5) return rgb;
        float c = amzp_clarity / 100.0;
        float2 texSz = getTexSize((screen.zw/1.0));
        float2 px = 1.0 / texSz;
        float3 t = amzTexture(0, clamp(uv + float2(0.0, -px.y * 2.0), 0.0, 1.0)).rgb;
        float3 b = amzTexture(0, clamp(uv + float2(0.0, px.y * 2.0), 0.0, 1.0)).rgb;
        float3 l = amzTexture(0, clamp(uv + float2(-px.x * 2.0, 0.0), 0.0, 1.0)).rgb;
        float3 r = amzTexture(0, clamp(uv + float2(px.x * 2.0, 0.0), 0.0, 1.0)).rgb;
        float localAvg = lum(t + b + l + r) * 0.25;
        float centerLum = lum(rgb);
        float detail = centerLum - localAvg;
        float midMask = 1.0 - abs(centerLum - 0.5) * 2.0;
        midMask = max(midMask, 0.0);
        rgb += detail * c * 1.5 * midMask;
        return rgb;
    }
    float3 applyDehaze(float3 rgb) {
        if (abs(amzp_dehaze) < 0.5) return rgb;
        float d = amzp_dehaze / 100.0;
        float l = lum(rgb);
        if (d > 0.0) {
            float hazeMask = 1.0 - smoothstep(0.0, 0.6, 1.0 - l);
            rgb = mix(rgb, rgb * (1.0 + d * 0.5), hazeMask);
            float satBoost = 1.0 + d * 0.15;
            rgb = mix(float3(lum(rgb)), rgb, satBoost);
        } else {
            float addHaze = abs(d);
            rgb = mix(rgb, float3(0.7, 0.75, 0.8), addHaze * 0.35);
        }
        return rgb;
    }
    float3 applyLiftGammaGain(float3 rgb) {
        float3 liftOff = (amzp_liftColor.rgb - 0.5) * 2.0;
        float liftL = amzp_liftLum / 100.0 * 0.3;
        float l = lum(rgb);
        float shadowMask = 1.0 - smoothstep(0.0, 0.5, l);
        rgb += (liftOff * 0.15 + liftL) * shadowMask;
        float3 gammaOff = (amzp_gammaColor.rgb - 0.5) * 2.0;
        float gammaL = amzp_gammaLum / 100.0 * 0.3;
        float midMask = smoothstep(0.0, 0.3, l) * smoothstep(1.0, 0.7, l);
        rgb += (gammaOff * 0.15 + gammaL) * midMask;
        float3 gainOff = (amzp_gainColor.rgb - 0.5) * 2.0;
        float gainL = amzp_gainLum / 100.0 * 0.3;
        float highMask = smoothstep(0.5, 1.0, l);
        rgb += (gainOff * 0.15 + gainL) * highMask;
        if (abs(gammaL) > 0.00001) {
            float gammaVal = 1.0 / max(1.0 + gammaL, 0.1);
            rgb = pow(max(rgb, 0.0), float3(gammaVal));
        }
        return rgb;
    }
    float3 applyColorWheels(float3 rgb) {
        float l = lum(rgb);
        float sMask = 1.0 - smoothstep(0.0, 0.5, l);
        sMask *= sMask;
        float mMask = smoothstep(0.0, 0.3, l) * smoothstep(1.0, 0.7, l);
        float hMask = smoothstep(0.5, 1.0, l);
        hMask *= hMask;
        float sStr = amzp_wheelShadowStr / 100.0;
        float mStr = amzp_wheelMidtoneStr / 100.0;
        float hStr = amzp_wheelHighlightStr / 100.0;
        float3 sOff = (amzp_wheelShadow.rgb - 0.5) * 2.0 * sStr;
        float3 mOff = (amzp_wheelMidtone.rgb - 0.5) * 2.0 * mStr;
        float3 hOff = (amzp_wheelHighlight.rgb - 0.5) * 2.0 * hStr;
        rgb += sOff * sMask * 0.2;
        rgb += mOff * mMask * 0.2;
        rgb += hOff * hMask * 0.2;
        float sLum = amzp_wheelShadowLum / 100.0 * 0.25;
        float mLum = amzp_wheelMidtoneLum / 100.0 * 0.25;
        float hLum = amzp_wheelHighlightLum / 100.0 * 0.25;
        rgb += sLum * sMask;
        rgb += mLum * mMask;
        rgb += hLum * hMask;
        return rgb;
    }
    float3 applySplitTone(float3 rgb) {
        float sStr = amzp_splitShadowStr / 100.0;
        float hStr = amzp_splitHighlightStr / 100.0;
        if (sStr < 0.00001 && hStr < 0.00001) return rgb;
        float l = lum(rgb);
        float balanceShift = amzp_splitBalance / 100.0 * 0.3;
        float sMask = 1.0 - smoothstep(0.0, 0.5 + balanceShift, l);
        float hMask = smoothstep(0.5 + balanceShift, 1.0, l);
        float3 sTint = (amzp_splitShadow.rgb - 0.5) * 2.0;
        float3 hTint = (amzp_splitHighlight.rgb - 0.5) * 2.0;
        float3 tinted = rgb;
        tinted += sTint * sStr * sMask * 0.2;
        tinted += hTint * hStr * hMask * 0.2;
        float origLum = lum(rgb);
        float newLum = lum(tinted);
        if (newLum > 0.00001) {
            tinted *= mix(1.0, origLum / newLum, 0.7);
        }
        return tinted;
    }
    float3 applyFadedFilm(float3 rgb) {
        if (amzp_fadedFilm < 0.5) return rgb;
        float f = amzp_fadedFilm / 100.0;
        float liftAmount = f * 0.12;
        rgb = rgb * (1.0 - f * 0.15) + liftAmount;
        float l = lum(rgb);
        rgb = mix(rgb, float3(l), f * 0.2);
        rgb = rgb * (1.0 - f * 0.1);
        return rgb;
    }
    float3 applySharpen(float3 rgb, float2 uv) {
        if (amzp_sharpen < 0.5) return rgb;
        float s = amzp_sharpen / 100.0 * 1.5;
        float2 px = 1.0 / getTexSize((screen.zw/1.0));
        float3 t = amzTexture(0, clamp(uv + float2(0.0, -px.y), 0.0, 1.0)).rgb;
        float3 b = amzTexture(0, clamp(uv + float2(0.0, px.y), 0.0, 1.0)).rgb;
        float3 l = amzTexture(0, clamp(uv + float2(-px.x, 0.0), 0.0, 1.0)).rgb;
        float3 r = amzTexture(0, clamp(uv + float2(px.x, 0.0), 0.0, 1.0)).rgb;
        float3 blur = (t + b + l + r) * 0.25;
        rgb += (rgb - blur) * s;
        return rgb;
    }
    float3 applyFilmGrain(float3 rgb, float2 uv) {
        if (amzp_filmGrain < 0.5) return rgb;
        float g = amzp_filmGrain / 100.0;
        float2 px = floor(getTexSize((screen.zw/1.0)) * uv);
        float n = noiseHash(px + time * 100.0) * 2.0 - 1.0;
        float l = lum(rgb);
        float grainMask = 1.0 - l * 0.4;
        rgb += n * g * 0.08 * grainMask;
        return rgb;
    }
    float3 applyBleachBypass(float3 rgb) {
        if (amzp_bleachBypass < 0.5) return rgb;
        float a = amzp_bleachBypass / 100.0;
        float l = lum(rgb);
        float3 desat = float3(l);
        float3 result;
        result.r = (l < 0.5) ? 2.0 * rgb.r * desat.r : 1.0 - 2.0 * (1.0 - rgb.r) * (1.0 - desat.r);
        result.g = (l < 0.5) ? 2.0 * rgb.g * desat.g : 1.0 - 2.0 * (1.0 - rgb.g) * (1.0 - desat.g);
        result.b = (l < 0.5) ? 2.0 * rgb.b * desat.b : 1.0 - 2.0 * (1.0 - rgb.b) * (1.0 - desat.b);
        return mix(rgb, result, a);
    }
    float3 applyCrossProcess(float3 rgb) {
        if (amzp_crossProcess < 0.5) return rgb;
        float a = amzp_crossProcess / 100.0;
        float3 cp;
        cp.r = pow(max(rgb.r, 0.0), 0.8 + a * 0.3);
        cp.g = pow(max(rgb.g, 0.0), 1.0 - a * 0.15);
        cp.b = pow(max(rgb.b, 0.0), 1.2 - a * 0.1);
        cp.r += a * 0.04;
        cp.b -= a * 0.02;
        return mix(rgb, cp, a);
    }
    float3 applyVignette(float3 rgb, float2 uv) {
        if (abs(amzp_vigAmount) < 0.5) return rgb;
        float amount = amzp_vigAmount / 100.0;
        float midpoint = amzp_vigMidpoint / 100.0;
        float roundness = amzp_vigRoundness / 100.0;
        float feather = amzp_vigFeather / 100.0;
        float2 center = uv - 0.5;
        center.x *= mix(1.5, 1.0, roundness);
        float dist = length(center);
        float vigRange = max(feather * 0.5, 0.01);
        float vig = smoothstep(midpoint - vigRange, midpoint + vigRange, dist);
        if (amount > 0.0) {
            rgb *= 1.0 - vig * amount;
        } else {
            rgb *= 1.0 + vig * abs(amount) * 0.5;
        }
        return rgb;
    }
    void amzRender() {
        float2 uv = amzScreenNorm();
        float4 original = amzTexture(0, uv);
        float3 rgb = max(original.rgb, 0.0);
        float3 baseRGB = rgb;
        rgb = applyWhiteBalance(rgb);
        rgb = applyExposure(rgb);
        rgb = applyContrast(rgb);
        rgb = applyHighlightsShadows(rgb);
        rgb = applySaturation(rgb);
        rgb = applyVibrance(rgb);
        rgb = applyClarity(rgb, uv);
        rgb = applyDehaze(rgb);
        float masterL = lum(rgb);
        float curvedL = applyCurve5(masterL, amzp_mcBlacks, amzp_mcShadows, amzp_mcMidtones, amzp_mcHighlights, amzp_mcWhites);
        float masterRatio = curvedL / max(masterL, 0.00001);
        rgb *= masterRatio;
        rgb.r = applyCurve3(rgb.r, amzp_rcShadows, amzp_rcMidtones, amzp_rcHighlights);
        rgb.g = applyCurve3(rgb.g, amzp_gcShadows, amzp_gcMidtones, amzp_gcHighlights);
        rgb.b = applyCurve3(rgb.b, amzp_bcShadows, amzp_bcMidtones, amzp_bcHighlights);
        rgb = applyLiftGammaGain(rgb);
        rgb = applyColorWheels(rgb);
        rgb = applySplitTone(rgb);
        rgb = applyFadedFilm(rgb);
        rgb = applySharpen(rgb, uv);
        rgb = applyFilmGrain(rgb, uv);
        rgb = applyBleachBypass(rgb);
        rgb = applyCrossProcess(rgb);
        rgb = applyVignette(rgb, uv);
        if (abs(amzp_masterGamma - 1.0) > 0.00001) {
            rgb = pow(max(rgb, 0.0), float3(1.0 / max(amzp_masterGamma, 0.00001)));
        }
        rgb *= amzp_masterGain;
        rgb += amzp_masterOffset;
        rgb = mix(baseRGB, rgb, amzp_globalMix);
        rgb = clamp(rgb, 0.0, 1.0);
        amzOutput = float4(rgb, original.a);
    }

half4 main(float2 coord) { amzCoord=coord*1.0; amzOutput=float4(0.0); amzRender(); return half4(amzOutput); }
